INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ದತ್ತಾಂಶ ಸಂಗ್ರಹಣೆ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 1)', 'ಸಮೀಕ್ಷೆ, ಸಂದರ್ಶನ, ವೀಕ್ಷಣೆ ಮತ್ತು ದಾಖಲೆಗಳ ಮೂಲಕ ಅಗತ್ಯ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದು', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಸಮೀಕ್ಷೆ, ಸಂದರ್ಶನ, ವೀಕ್ಷಣೆ ಮತ್ತು ದಾಖಲೆಗಳ ಮೂಲಕ ಅಗತ್ಯ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದು', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ದತ್ತಾಂಶ ಶುದ್ಧೀಕರಣ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 2)', 'ಖಾಲಿ, ನಕಲಿ, ತಪ್ಪಾದ ಮತ್ತು ಅಸಂಗತ ದಾಖಲೆಗಳನ್ನು ಗುರುತಿಸಿ ಸರಿಪಡಿಸುವುದು', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಖಾಲಿ, ನಕಲಿ, ತಪ್ಪಾದ ಮತ್ತು ಅಸಂಗತ ದಾಖಲೆಗಳನ್ನು ಗುರುತಿಸಿ ಸರಿಪಡಿಸುವುದು', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ಸರಾಸರಿ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 3)', 'ಎಲ್ಲಾ ಮೌಲ್ಯಗಳ ಮೊತ್ತವನ್ನು ಮೌಲ್ಯಗಳ ಸಂಖ್ಯೆಯಿಂದ ಭಾಗಿಸಿ ಪಡೆಯುವ ಕೇಂದ್ರ ಮೌಲ್ಯ', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಎಲ್ಲಾ ಮೌಲ್ಯಗಳ ಮೊತ್ತವನ್ನು ಮೌಲ್ಯಗಳ ಸಂಖ್ಯೆಯಿಂದ ಭಾಗಿಸಿ ಪಡೆಯುವ ಕೇಂದ್ರ ಮೌಲ್ಯ', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ಮಧ್ಯಕ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 4)', 'ಕ್ರಮಬದ್ಧ ದತ್ತಾಂಶದ ಮಧ್ಯದಲ್ಲಿರುವ ಕೇಂದ್ರ ಮೌಲ್ಯ', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಕ್ರಮಬದ್ಧ ದತ್ತಾಂಶದ ಮಧ್ಯದಲ್ಲಿರುವ ಕೇಂದ್ರ ಮೌಲ್ಯ', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ಬಹುಲಕ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 5)', 'ದತ್ತಾಂಶದಲ್ಲಿ ಅತಿ ಹೆಚ್ಚು ಬಾರಿ ಕಾಣಿಸುವ ಮೌಲ್ಯ', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ದತ್ತಾಂಶದಲ್ಲಿ ಅತಿ ಹೆಚ್ಚು ಬಾರಿ ಕಾಣಿಸುವ ಮೌಲ್ಯ', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ವ್ಯಾಪ್ತಿ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 6)', 'ಗರಿಷ್ಠ ಮತ್ತು ಕನಿಷ್ಠ ಮೌಲ್ಯಗಳ ನಡುವಿನ ಅಂತರ', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಗರಿಷ್ಠ ಮತ್ತು ಕನಿಷ್ಠ ಮೌಲ್ಯಗಳ ನಡುವಿನ ಅಂತರ', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ಸಹಸಂಬಂಧ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 7)', 'ಎರಡು ಚರಗಳು ಪರಸ್ಪರ ಹೇಗೆ ಬದಲಾಗುತ್ತವೆ ಎಂಬ ಸಂಬಂಧದ ದಿಕ್ಕು ಮತ್ತು ಬಲ', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಎರಡು ಚರಗಳು ಪರಸ್ಪರ ಹೇಗೆ ಬದಲಾಗುತ್ತವೆ ಎಂಬ ಸಂಬಂಧದ ದಿಕ್ಕು ಮತ್ತು ಬಲ', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ಕಾರಣಕಾರಿತ್ವ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 8)', 'ಒಂದು ಅಂಶದ ಬದಲಾವಣೆಯಿಂದ ಮತ್ತೊಂದು ಅಂಶದಲ್ಲಿ ಪರಿಣಾಮ ಉಂಟಾಗುವ ಕಾರಣ-ಪರಿಣಾಮ ಸಂಬಂಧ', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಒಂದು ಅಂಶದ ಬದಲಾವಣೆಯಿಂದ ಮತ್ತೊಂದು ಅಂಶದಲ್ಲಿ ಪರಿಣಾಮ ಉಂಟಾಗುವ ಕಾರಣ-ಪರಿಣಾಮ ಸಂಬಂಧ', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ಅತಿರೇಕ ಮೌಲ್ಯ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 9)', 'ಸಾಮಾನ್ಯ ಮೌಲ್ಯಗಳಿಂದ ಬಹಳ ದೂರದಲ್ಲಿರುವ ಅಸಾಮಾನ್ಯ ಮೌಲ್ಯ', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಸಾಮಾನ್ಯ ಮೌಲ್ಯಗಳಿಂದ ಬಹಳ ದೂರದಲ್ಲಿರುವ ಅಸಾಮಾನ್ಯ ಮೌಲ್ಯ', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ದತ್ತಾಂಶ ದೃಶ್ಯೀಕರಣ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 10)', 'ದತ್ತಾಂಶವನ್ನು ರೇಖೆ, ಸ್ತಂಭ, ವೃತ್ತ ಅಥವಾ ಇತರ ದೃಶ್ಯ ರೂಪದಲ್ಲಿ ತೋರಿಸುವುದು', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ದತ್ತಾಂಶವನ್ನು ರೇಖೆ, ಸ್ತಂಭ, ವೃತ್ತ ಅಥವಾ ಇತರ ದೃಶ್ಯ ರೂಪದಲ್ಲಿ ತೋರಿಸುವುದು', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ವಿವರಣಾತ್ಮಕ ವಿಶ್ಲೇಷಣೆ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 11)', 'ಹಿಂದೆ ನಡೆದ ಅಥವಾ ಪ್ರಸ್ತುತ ಸ್ಥಿತಿಯ ದತ್ತಾಂಶವನ್ನು ಸಾರಾಂಶಗೊಳಿಸಿ ವಿವರಿಸುವುದು', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಹಿಂದೆ ನಡೆದ ಅಥವಾ ಪ್ರಸ್ತುತ ಸ್ಥಿತಿಯ ದತ್ತಾಂಶವನ್ನು ಸಾರಾಂಶಗೊಳಿಸಿ ವಿವರಿಸುವುದು', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಏಕ ಆಯ್ಕೆ', 'ಸುಲಭ', '1', 'ಭವಿಷ್ಯಾನುಮಾನ ವಿಶ್ಲೇಷಣೆ ಕುರಿತು ಕೆಳಗಿನ ಯಾವ ಹೇಳಿಕೆ ಸರಿಯಾಗಿದೆ? (ಪ್ರಶ್ನೆ 12)', 'ಹಿಂದಿನ ದತ್ತಾಂಶದ ಆಧಾರದ ಮೇಲೆ ಭವಿಷ್ಯದ ಸಾಧ್ಯ ಫಲಿತಾಂಶಗಳನ್ನು ಅಂದಾಜಿಸುವುದು', 'ಸಂಬಂಧವಿಲ್ಲದ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸುವುದು', 'ಕೇವಲ ದಾಖಲೆಗಳನ್ನು ಮುದ್ರಿಸುವುದು', 'ಚಿತ್ರದ ಗಾತ್ರ ಬದಲಿಸುವುದು', 'ಹಿಂದಿನ ದತ್ತಾಂಶದ ಆಧಾರದ ಮೇಲೆ ಭವಿಷ್ಯದ ಸಾಧ್ಯ ಫಲಿತಾಂಶಗಳನ್ನು ಅಂದಾಜಿಸುವುದು', 'ಸರಿಯಾದ ಉತ್ತರವು ಕೇಳಲಾದ ಪರಿಕಲ್ಪನೆಯ ಸರಿಯಾದ ವಿವರಣೆಯಾಗಿದೆ.'),
