('KA-Business Analytics', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಖಾಲಿ, ನಕಲಿ, ತಪ್ಪಾದ ಮತ್ತು ಅಸಂಗತ ದಾಖಲೆಗಳನ್ನು ಗುರುತಿಸಿ ಸರಿಪಡಿಸುವುದು ಎಂಬ ಪ್ರಕ್ರಿಯೆಯನ್ನು ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಶುದ್ಧೀಕರಣ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಎಲ್ಲಾ ಮೌಲ್ಯಗಳ ಮೊತ್ತವನ್ನು ಮೌಲ್ಯಗಳ ಸಂಖ್ಯೆಯಿಂದ ಭಾಗಿಸಿ ಪಡೆಯುವ ಕೇಂದ್ರ ಮೌಲ್ಯ ಎಂಬ ಪ್ರಕ್ರಿಯೆಯನ್ನು ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಸರಾಸರಿ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಕಾರಣಕಾರಿತ್ವ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಕಾರಣಕಾರಿತ್ವ ಎಂದರೆ ಒಂದು ಅಂಶದ ಬದಲಾವಣೆಯಿಂದ ಮತ್ತೊಂದು ಅಂಶದಲ್ಲಿ ಪರಿಣಾಮ ಉಂಟಾಗುವ ಕಾರಣ-ಪರಿಣಾಮ ಸಂಬಂಧ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಅತಿರೇಕ ಮೌಲ್ಯ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಅತಿರೇಕ ಮೌಲ್ಯ ಎಂದರೆ ಸಾಮಾನ್ಯ ಮೌಲ್ಯಗಳಿಂದ ಬಹಳ ದೂರದಲ್ಲಿರುವ ಅಸಾಮಾನ್ಯ ಮೌಲ್ಯ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ದತ್ತಾಂಶ ದೃಶ್ಯೀಕರಣ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ದೃಶ್ಯೀಕರಣ ಎಂದರೆ ದತ್ತಾಂಶವನ್ನು ರೇಖೆ, ಸ್ತಂಭ, ವೃತ್ತ ಅಥವಾ ಇತರ ದೃಶ್ಯ ರೂಪದಲ್ಲಿ ತೋರಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ವಿವರಣಾತ್ಮಕ ವಿಶ್ಲೇಷಣೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ವಿವರಣಾತ್ಮಕ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಹಿಂದೆ ನಡೆದ ಅಥವಾ ಪ್ರಸ್ತುತ ಸ್ಥಿತಿಯ ದತ್ತಾಂಶವನ್ನು ಸಾರಾಂಶಗೊಳಿಸಿ ವಿವರಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಭವಿಷ್ಯಾನುಮಾನ ವಿಶ್ಲೇಷಣೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಭವಿಷ್ಯಾನುಮಾನ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಹಿಂದಿನ ದತ್ತಾಂಶದ ಆಧಾರದ ಮೇಲೆ ಭವಿಷ್ಯದ ಸಾಧ್ಯ ಫಲಿತಾಂಶಗಳನ್ನು ಅಂದಾಜಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಗ್ರಾಹಕ ವಿಭಾಗೀಕರಣ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಗ್ರಾಹಕ ವಿಭಾಗೀಕರಣ ಎಂದರೆ ಸಮಾನ ಗುಣಲಕ್ಷಣ ಅಥವಾ ವರ್ತನೆಯ ಗ್ರಾಹಕರನ್ನು ಗುಂಪುಗಳಾಗಿ ವಿಂಗಡಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಪ್ರಮುಖ ಕಾರ್ಯಕ್ಷಮತಾ ಸೂಚಕ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಪ್ರಮುಖ ಕಾರ್ಯಕ್ಷಮತಾ ಸೂಚಕ ಎಂದರೆ ಗುರಿ ಸಾಧನೆಯ ಮಟ್ಟವನ್ನು ಅಳೆಯುವ ಪ್ರಮುಖ ಅಳತೆ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಸೂಚಕ ಫಲಕ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಸೂಚಕ ಫಲಕ ಎಂದರೆ ಮುಖ್ಯ ವ್ಯವಹಾರ ಸೂಚಕಗಳನ್ನು ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ ಸುಲಭವಾಗಿ ವೀಕ್ಷಿಸಲು ಬಳಸುವ ವ್ಯವಸ್ಥೆ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಬಜೆಟ್ ವಿಶ್ಲೇಷಣೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಬಜೆಟ್ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಯೋಜಿತ ಮತ್ತು ನಿಜವಾದ ಆದಾಯ ಹಾಗೂ ವೆಚ್ಚವನ್ನು ಹೋಲಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಮಾರುಕಟ್ಟೆ ವಿಶ್ಲೇಷಣೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಮಾರುಕಟ್ಟೆ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಬೇಡಿಕೆ, ಗ್ರಾಹಕರು, ಸ್ಪರ್ಧೆ ಮತ್ತು ಬೆಲೆಗಳ ಸ್ಥಿತಿಯನ್ನು ಅಧ್ಯಯನ ಮಾಡುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಲಾಭ ವಿಶ್ಲೇಷಣೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಲಾಭ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಆದಾಯ, ವೆಚ್ಚ ಮತ್ತು ಮಾರಾಟದ ಆಧಾರದ ಮೇಲೆ ಲಾಭದ ಸ್ಥಿತಿಯನ್ನು ಪರಿಶೀಲಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಸಮಯ ಸರಣಿ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಸಮಯ ಸರಣಿ ಎಂದರೆ ಸಮಯದ ಕ್ರಮದಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾದ ದತ್ತಾಂಶ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ದತ್ತಾಂಶ ನಿಖರತೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ನಿಖರತೆ ಎಂದರೆ ದತ್ತಾಂಶವು ನಿಜವಾದ ಸ್ಥಿತಿಗೆ ಸರಿಯಾಗಿ ಹೊಂದಿಕೆಯಾಗಿರುವ ಗುಣ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ದತ್ತಾಂಶ ಸಂಪೂರ್ಣತೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಸಂಪೂರ್ಣತೆ ಎಂದರೆ ಅಗತ್ಯ ಮಾಹಿತಿಯು ಸಮರ್ಪಕವಾಗಿ ಲಭ್ಯವಿರುವ ಗುಣ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ದತ್ತಾಂಶ ಸಮ್ಮತತೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಸಮ್ಮತತೆ ಎಂದರೆ ವಿವಿಧ ದಾಖಲೆಗಳಲ್ಲಿನ ಮಾಹಿತಿ ಪರಸ್ಪರ ಹೊಂದಿಕೆಯಾಗಿರುವ ಗುಣ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಮಾಹಿತಿ ಗೌಪ್ಯತೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಮಾಹಿತಿ ಗೌಪ್ಯತೆ ಎಂದರೆ ಅನುಮತಿ ಇಲ್ಲದ ಪ್ರವೇಶದಿಂದ ಸೂಕ್ಷ್ಮ ಮಾಹಿತಿಯನ್ನು ರಕ್ಷಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಮಾದರಿ ಆಯ್ಕೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಮಾದರಿ ಆಯ್ಕೆ ಎಂದರೆ ಒಟ್ಟು ಸಮೂಹದಿಂದ ಪ್ರತಿನಿಧಿಸುವ ಕೆಲವು ಘಟಕಗಳನ್ನು ಆರಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಗ್ರಾಹಕ ತೃಪ್ತಿ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಗ್ರಾಹಕ ತೃಪ್ತಿ ಎಂದರೆ ಗ್ರಾಹಕರ ಅನುಭವ ಮತ್ತು ನಿರೀಕ್ಷೆ ಪೂರೈಸಿದ ಮಟ್ಟ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಮಾರಾಟ ವಿಶ್ಲೇಷಣೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಮಾರಾಟ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಕಾಲ, ಪ್ರದೇಶ, ಉತ್ಪನ್ನ ಮತ್ತು ಗ್ರಾಹಕರ ಆಧಾರದ ಮೇಲೆ ಮಾರಾಟವನ್ನು ಪರಿಶೀಲಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ವೆಚ್ಚ ನಿಯಂತ್ರಣ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ವೆಚ್ಚ ನಿಯಂತ್ರಣ ಎಂದರೆ ಅನಗತ್ಯ ವೆಚ್ಚವನ್ನು ಗುರುತಿಸಿ ನಿಯಂತ್ರಿಸುವ ಪ್ರಕ್ರಿಯೆ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಮೂಲ ಕಾರಣ ವಿಶ್ಲೇಷಣೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಮೂಲ ಕಾರಣ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ವ್ಯವಹಾರ ಸಮಸ್ಯೆಯ ಮೇಲ್ಮೈ ಲಕ್ಷಣದ ಬದಲು ಅದರ ಮೂಲ ಕಾರಣವನ್ನು ಕಂಡುಹಿಡಿಯುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಅಪಾಯ ವಿಶ್ಲೇಷಣೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಅಪಾಯ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಸಂಭಾವ್ಯ ಅಪಾಯದ ಸಾಧ್ಯತೆ ಮತ್ತು ಪರಿಣಾಮವನ್ನು ಪರಿಶೀಲಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ದತ್ತಾಂಶ ಆಧಾರಿತ ನಿರ್ಧಾರ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಆಧಾರಿತ ನಿರ್ಧಾರ ಎಂದರೆ ವಿಶ್ವಾಸಾರ್ಹ ದತ್ತಾಂಶ ಮತ್ತು ವಿಶ್ಲೇಷಣೆಯ ಆಧಾರದ ಮೇಲೆ ನಿರ್ಧಾರ ಕೈಗೊಳ್ಳುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ದತ್ತಾಂಶ ಸಂಗ್ರಹಣೆ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಸಂಗ್ರಹಣೆ ಎಂದರೆ ಸಮೀಕ್ಷೆ, ಸಂದರ್ಶನ, ವೀಕ್ಷಣೆ ಮತ್ತು ದಾಖಲೆಗಳ ಮೂಲಕ ಅಗತ್ಯ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ದತ್ತಾಂಶ ಶುದ್ಧೀಕರಣ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಶುದ್ಧೀಕರಣ ಎಂದರೆ ಖಾಲಿ, ನಕಲಿ, ತಪ್ಪಾದ ಮತ್ತು ಅಸಂಗತ ದಾಖಲೆಗಳನ್ನು ಗುರುತಿಸಿ ಸರಿಪಡಿಸುವುದು. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಸರಾಸರಿ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಸರಾಸರಿ ಎಂದರೆ ಎಲ್ಲಾ ಮೌಲ್ಯಗಳ ಮೊತ್ತವನ್ನು ಮೌಲ್ಯಗಳ ಸಂಖ್ಯೆಯಿಂದ ಭಾಗಿಸಿ ಪಡೆಯುವ ಕೇಂದ್ರ ಮೌಲ್ಯ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಮಧ್ಯಕ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಮಧ್ಯಕ ಎಂದರೆ ಕ್ರಮಬದ್ಧ ದತ್ತಾಂಶದ ಮಧ್ಯದಲ್ಲಿರುವ ಕೇಂದ್ರ ಮೌಲ್ಯ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಬಹುಲಕ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಬಹುಲಕ ಎಂದರೆ ದತ್ತಾಂಶದಲ್ಲಿ ಅತಿ ಹೆಚ್ಚು ಬಾರಿ ಕಾಣಿಸುವ ಮೌಲ್ಯ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ವ್ಯಾಪ್ತಿ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ವ್ಯಾಪ್ತಿ ಎಂದರೆ ಗರಿಷ್ಠ ಮತ್ತು ಕನಿಷ್ಠ ಮೌಲ್ಯಗಳ ನಡುವಿನ ಅಂತರ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಸಹಸಂಬಂಧ ಎಂದರೇನು? ಅದರ ಒಂದು ಮುಖ್ಯ ಉಪಯೋಗವನ್ನು ಬರೆಯಿರಿ.', NULL, NULL, NULL, NULL, 'ಸಹಸಂಬಂಧ ಎಂದರೆ ಎರಡು ಚರಗಳು ಪರಸ್ಪರ ಹೇಗೆ ಬದಲಾಗುತ್ತವೆ ಎಂಬ ಸಂಬಂಧದ ದಿಕ್ಕು ಮತ್ತು ಬಲ. ಇದು ವ್ಯವಹಾರ ಸಮಸ್ಯೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ಸೂಕ್ತ ನಿರ್ಧಾರಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.', 'ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ ಮತ್ತು ಅದರ ಉಪಯೋಗವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಭವಿಷ್ಯಾನುಮಾನ ವಿಶ್ಲೇಷಣೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಭವಿಷ್ಯಾನುಮಾನ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಹಿಂದಿನ ದತ್ತಾಂಶದ ಆಧಾರದ ಮೇಲೆ ಭವಿಷ್ಯದ ಸಾಧ್ಯ ಫಲಿತಾಂಶಗಳನ್ನು ಅಂದಾಜಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಗ್ರಾಹಕ ವಿಭಾಗೀಕರಣ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಗ್ರಾಹಕ ವಿಭಾಗೀಕರಣ ಎಂದರೆ ಸಮಾನ ಗುಣಲಕ್ಷಣ ಅಥವಾ ವರ್ತನೆಯ ಗ್ರಾಹಕರನ್ನು ಗುಂಪುಗಳಾಗಿ ವಿಂಗಡಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಪ್ರಮುಖ ಕಾರ್ಯಕ್ಷಮತಾ ಸೂಚಕ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪ್ರಮುಖ ಕಾರ್ಯಕ್ಷಮತಾ ಸೂಚಕ ಎಂದರೆ ಗುರಿ ಸಾಧನೆಯ ಮಟ್ಟವನ್ನು ಅಳೆಯುವ ಪ್ರಮುಖ ಅಳತೆ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಸೂಚಕ ಫಲಕ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಸೂಚಕ ಫಲಕ ಎಂದರೆ ಮುಖ್ಯ ವ್ಯವಹಾರ ಸೂಚಕಗಳನ್ನು ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ ಸುಲಭವಾಗಿ ವೀಕ್ಷಿಸಲು ಬಳಸುವ ವ್ಯವಸ್ಥೆ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಬಜೆಟ್ ವಿಶ್ಲೇಷಣೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಬಜೆಟ್ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಯೋಜಿತ ಮತ್ತು ನಿಜವಾದ ಆದಾಯ ಹಾಗೂ ವೆಚ್ಚವನ್ನು ಹೋಲಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಮಾರುಕಟ್ಟೆ ವಿಶ್ಲೇಷಣೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮಾರುಕಟ್ಟೆ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಬೇಡಿಕೆ, ಗ್ರಾಹಕರು, ಸ್ಪರ್ಧೆ ಮತ್ತು ಬೆಲೆಗಳ ಸ್ಥಿತಿಯನ್ನು ಅಧ್ಯಯನ ಮಾಡುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಲಾಭ ವಿಶ್ಲೇಷಣೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಲಾಭ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಆದಾಯ, ವೆಚ್ಚ ಮತ್ತು ಮಾರಾಟದ ಆಧಾರದ ಮೇಲೆ ಲಾಭದ ಸ್ಥಿತಿಯನ್ನು ಪರಿಶೀಲಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಸಮಯ ಸರಣಿ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಸಮಯ ಸರಣಿ ಎಂದರೆ ಸಮಯದ ಕ್ರಮದಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾದ ದತ್ತಾಂಶ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ದತ್ತಾಂಶ ನಿಖರತೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ನಿಖರತೆ ಎಂದರೆ ದತ್ತಾಂಶವು ನಿಜವಾದ ಸ್ಥಿತಿಗೆ ಸರಿಯಾಗಿ ಹೊಂದಿಕೆಯಾಗಿರುವ ಗುಣ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ದತ್ತಾಂಶ ಸಂಪೂರ್ಣತೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಸಂಪೂರ್ಣತೆ ಎಂದರೆ ಅಗತ್ಯ ಮಾಹಿತಿಯು ಸಮರ್ಪಕವಾಗಿ ಲಭ್ಯವಿರುವ ಗುಣ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ದತ್ತಾಂಶ ಸಮ್ಮತತೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಸಮ್ಮತತೆ ಎಂದರೆ ವಿವಿಧ ದಾಖಲೆಗಳಲ್ಲಿನ ಮಾಹಿತಿ ಪರಸ್ಪರ ಹೊಂದಿಕೆಯಾಗಿರುವ ಗುಣ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಮಾಹಿತಿ ಗೌಪ್ಯತೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮಾಹಿತಿ ಗೌಪ್ಯತೆ ಎಂದರೆ ಅನುಮತಿ ಇಲ್ಲದ ಪ್ರವೇಶದಿಂದ ಸೂಕ್ಷ್ಮ ಮಾಹಿತಿಯನ್ನು ರಕ್ಷಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಮಾದರಿ ಆಯ್ಕೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮಾದರಿ ಆಯ್ಕೆ ಎಂದರೆ ಒಟ್ಟು ಸಮೂಹದಿಂದ ಪ್ರತಿನಿಧಿಸುವ ಕೆಲವು ಘಟಕಗಳನ್ನು ಆರಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಗ್ರಾಹಕ ತೃಪ್ತಿ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಗ್ರಾಹಕ ತೃಪ್ತಿ ಎಂದರೆ ಗ್ರಾಹಕರ ಅನುಭವ ಮತ್ತು ನಿರೀಕ್ಷೆ ಪೂರೈಸಿದ ಮಟ್ಟ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಮಾರಾಟ ವಿಶ್ಲೇಷಣೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮಾರಾಟ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಕಾಲ, ಪ್ರದೇಶ, ಉತ್ಪನ್ನ ಮತ್ತು ಗ್ರಾಹಕರ ಆಧಾರದ ಮೇಲೆ ಮಾರಾಟವನ್ನು ಪರಿಶೀಲಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ವೆಚ್ಚ ನಿಯಂತ್ರಣ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ವೆಚ್ಚ ನಿಯಂತ್ರಣ ಎಂದರೆ ಅನಗತ್ಯ ವೆಚ್ಚವನ್ನು ಗುರುತಿಸಿ ನಿಯಂತ್ರಿಸುವ ಪ್ರಕ್ರಿಯೆ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಮೂಲ ಕಾರಣ ವಿಶ್ಲೇಷಣೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮೂಲ ಕಾರಣ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ವ್ಯವಹಾರ ಸಮಸ್ಯೆಯ ಮೇಲ್ಮೈ ಲಕ್ಷಣದ ಬದಲು ಅದರ ಮೂಲ ಕಾರಣವನ್ನು ಕಂಡುಹಿಡಿಯುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಅಪಾಯ ವಿಶ್ಲೇಷಣೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಅಪಾಯ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಸಂಭಾವ್ಯ ಅಪಾಯದ ಸಾಧ್ಯತೆ ಮತ್ತು ಪರಿಣಾಮವನ್ನು ಪರಿಶೀಲಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ದತ್ತಾಂಶ ಆಧಾರಿತ ನಿರ್ಧಾರ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಆಧಾರಿತ ನಿರ್ಧಾರ ಎಂದರೆ ವಿಶ್ವಾಸಾರ್ಹ ದತ್ತಾಂಶ ಮತ್ತು ವಿಶ್ಲೇಷಣೆಯ ಆಧಾರದ ಮೇಲೆ ನಿರ್ಧಾರ ಕೈಗೊಳ್ಳುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ದತ್ತಾಂಶ ಸಂಗ್ರಹಣೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಸಂಗ್ರಹಣೆ ಎಂದರೆ ಸಮೀಕ್ಷೆ, ಸಂದರ್ಶನ, ವೀಕ್ಷಣೆ ಮತ್ತು ದಾಖಲೆಗಳ ಮೂಲಕ ಅಗತ್ಯ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ದತ್ತಾಂಶ ಶುದ್ಧೀಕರಣ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ಶುದ್ಧೀಕರಣ ಎಂದರೆ ಖಾಲಿ, ನಕಲಿ, ತಪ್ಪಾದ ಮತ್ತು ಅಸಂಗತ ದಾಖಲೆಗಳನ್ನು ಗುರುತಿಸಿ ಸರಿಪಡಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಸರಾಸರಿ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಸರಾಸರಿ ಎಂದರೆ ಎಲ್ಲಾ ಮೌಲ್ಯಗಳ ಮೊತ್ತವನ್ನು ಮೌಲ್ಯಗಳ ಸಂಖ್ಯೆಯಿಂದ ಭಾಗಿಸಿ ಪಡೆಯುವ ಕೇಂದ್ರ ಮೌಲ್ಯ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಮಧ್ಯಕ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮಧ್ಯಕ ಎಂದರೆ ಕ್ರಮಬದ್ಧ ದತ್ತಾಂಶದ ಮಧ್ಯದಲ್ಲಿರುವ ಕೇಂದ್ರ ಮೌಲ್ಯ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಬಹುಲಕ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಬಹುಲಕ ಎಂದರೆ ದತ್ತಾಂಶದಲ್ಲಿ ಅತಿ ಹೆಚ್ಚು ಬಾರಿ ಕಾಣಿಸುವ ಮೌಲ್ಯ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ವ್ಯಾಪ್ತಿ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ವ್ಯಾಪ್ತಿ ಎಂದರೆ ಗರಿಷ್ಠ ಮತ್ತು ಕನಿಷ್ಠ ಮೌಲ್ಯಗಳ ನಡುವಿನ ಅಂತರ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಸಹಸಂಬಂಧ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಸಹಸಂಬಂಧ ಎಂದರೆ ಎರಡು ಚರಗಳು ಪರಸ್ಪರ ಹೇಗೆ ಬದಲಾಗುತ್ತವೆ ಎಂಬ ಸಂಬಂಧದ ದಿಕ್ಕು ಮತ್ತು ಬಲ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಕಾರಣಕಾರಿತ್ವ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕಾರಣಕಾರಿತ್ವ ಎಂದರೆ ಒಂದು ಅಂಶದ ಬದಲಾವಣೆಯಿಂದ ಮತ್ತೊಂದು ಅಂಶದಲ್ಲಿ ಪರಿಣಾಮ ಉಂಟಾಗುವ ಕಾರಣ-ಪರಿಣಾಮ ಸಂಬಂಧ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಅತಿರೇಕ ಮೌಲ್ಯ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಅತಿರೇಕ ಮೌಲ್ಯ ಎಂದರೆ ಸಾಮಾನ್ಯ ಮೌಲ್ಯಗಳಿಂದ ಬಹಳ ದೂರದಲ್ಲಿರುವ ಅಸಾಮಾನ್ಯ ಮೌಲ್ಯ. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ದತ್ತಾಂಶ ದೃಶ್ಯೀಕರಣ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ದತ್ತಾಂಶ ದೃಶ್ಯೀಕರಣ ಎಂದರೆ ದತ್ತಾಂಶವನ್ನು ರೇಖೆ, ಸ್ತಂಭ, ವೃತ್ತ ಅಥವಾ ಇತರ ದೃಶ್ಯ ರೂಪದಲ್ಲಿ ತೋರಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Business Analytics', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ವಿವರಣಾತ್ಮಕ ವಿಶ್ಲೇಷಣೆ ಅನ್ನು ವ್ಯವಹಾರ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಹೇಗೆ ಬಳಸಬಹುದು? ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ವಿವರಣಾತ್ಮಕ ವಿಶ್ಲೇಷಣೆ ಎಂದರೆ ಹಿಂದೆ ನಡೆದ ಅಥವಾ ಪ್ರಸ್ತುತ ಸ್ಥಿತಿಯ ದತ್ತಾಂಶವನ್ನು ಸಾರಾಂಶಗೊಳಿಸಿ ವಿವರಿಸುವುದು. ಇದನ್ನು ಬಳಸುವಾಗ ಮೊದಲು ವ್ಯವಹಾರದ ಗುರಿ ಮತ್ತು ಅಗತ್ಯವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಬೇಕು. ನಂತರ ಸಂಬಂಧಿತ ದತ್ತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಿ ಅದರ ಗುಣಮಟ್ಟವನ್ನು ಪರಿಶೀಲಿಸಬೇಕು. ಸೂಕ್ತ ವಿಧಾನದಲ್ಲಿ ವಿಶ್ಲೇಷಣೆ ಮಾಡಿ ಕಂಡುಬಂದ ಫಲಿತಾಂಶವನ್ನು ವ್ಯವಹಾರದ ಸಂದರ್ಭಕ್ಕೆ ಜೋಡಿಸಬೇಕು. ಅಂತಿಮವಾಗಿ ಫಲಿತಾಂಶವನ್ನು ಗುರಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ ಅಗತ್ಯ ನಿರ್ಧಾರ ಅಥವಾ ತಿದ್ದುಪಡಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಬಳಕೆ, ವಿಶ್ಲೇಷಣಾ ಕ್ರಮ ಮತ್ತು ನಿರ್ಧಾರಕ್ಕೆ ಅದರ ಸಂಬಂಧವನ್ನು ವಿವರಿಸಲಾಗಿದೆ.');